[CmdletBinding()]param([ValidateSet('Launch')][string]$Phase='Launch',[Parameter(Mandatory=$true)][string]$CompileReceiptSha256,[Parameter(Mandatory=$true)][string]$ExeSha256,[Parameter(Mandatory=$true)][string]$SerializerControlSha256,[Parameter(Mandatory=$true)][string]$SourceInputsPath,[Parameter(Mandatory=$true)][string]$SourceInputsHash,[Parameter(Mandatory=$true)][string]$PlanPath,[Parameter(Mandatory=$true)][string]$PlanHash,[Parameter(Mandatory=$true)][string]$CompileReceiptPath,[Parameter(Mandatory=$true)][string]$ExePath,[Parameter(Mandatory=$true)][string]$RendererPath,[Parameter(Mandatory=$true)][string]$SerializerPath)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot 'diagnostic-profile.ps1')
if((Get-DiagnosticHash $SourceInputsPath) -cne $SourceInputsHash -or (Get-DiagnosticHash $PlanPath) -cne $PlanHash -or (Get-DiagnosticHash $CompileReceiptPath) -cne $CompileReceiptSha256 -or (Get-DiagnosticHash $ExePath) -cne $ExeSha256){throw 'Diagnostic preflight byte pin drift'}
$si=Get-DiagnosticJson $SourceInputsPath;$plan=Get-DiagnosticJson $PlanPath;$receipt=Get-DiagnosticJson $CompileReceiptPath;$tuple=Get-DiagnosticJson (Assert-DiagnosticRef $si.tupleRef 'tuple');Assert-CircleDiagnosticPlanReceipt $si $plan $receipt $tuple|Out-Null
if($si.serializerControlSha256 -cne $SerializerControlSha256 -or (Get-DiagnosticHash $SerializerPath) -cne $SerializerControlSha256){throw 'Diagnostic serializer pin drift'}
if($plan.rendererPath -ne $si.rendererPath -or $plan.rendererSha256 -ne $si.rendererSha256){throw 'Diagnostic renderer join drift'}
[ordered]@{kind='factory-circle-diagnostic-preflight-v1';status='passed-source-only';nativeActions=0;compilerActions=0;lockActions=0}|ConvertTo-Json -Compress
